var n=`0341-schweinshaxe`;var t=`world-0341`;var a=`DE`;var s=`western-europe`;var r=4;var o=147;var l={en:`Schweinshaxe`,ua:`Свиняча рулька по-німецьки`};var d={en:`A traditional Germany dish made with pork knuckle, bay leaf, yellow onion, sea salt. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: свиняча рулька на кістці, лавровий лист, жовта цибуля, морська сіль. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Cook the listed ingredients in simmering water for about 85 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 85 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:85,i:[[`pork-knuckle`,1300,`g`],[`water`,1600,`ml`],[`bay-leaf`,3,`leaf`],[`yellow-onion`,180,`g`],[`caraway-seeds`,5,`g`]]},{en:`Dry the simmered pork knuckle, score the rind and roast at 220°C then lower heat; baste with beer until crackling is crisp and meat tender.`,ua:`Обсушіть відварену рульку, надріжте шкірку й спочатку запікайте при 220°C, потім зменшіть жар; поливайте пивом до хрусткої скоринки та м’якості м’яса.`,t:[`roasting`],m:60,i:[[`light-beer`,260,`ml`],[`sea-salt`,12,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`dijon-mustard`,70,`g`]]}];var g={slug:n,id:t,country:`DE`,region:s,servings:4,minutes:147,title:l,text:d,steps:h};export{a as country,g as default,t as id,o as minutes,s as region,r as servings,n as slug,h as steps,d as text,l as title};